import type { NotionContrastMode } from "@notionhq/custom-blocks-protocol/contrast.js"
import type { NotionDataSource } from "@notionhq/custom-blocks-protocol/dataSources/dataSource.js"
import type { NotionDataSourcePageBridge } from "@notionhq/custom-blocks-protocol/dataSources/dataSourcePage.js"
import type { NotionDataSourceValue } from "@notionhq/custom-blocks-protocol/dataSources/dataSourceValue.js"
import type { NotionPropertySchema } from "@notionhq/custom-blocks-protocol/dataSources/propertySchema.js"
import type {
	NotionBlockId,
	NotionPageId,
} from "@notionhq/custom-blocks-protocol/ids.js"
import type { CustomBlockManifest } from "@notionhq/custom-blocks-protocol/manifest.js"
import type { CustomBlockQueryDataSourceErrorInfo } from "@notionhq/custom-blocks-protocol/messages/queryDataSourceResult.js"
import type { CustomBlockPage } from "@notionhq/custom-blocks-protocol/pages/page.js"
import type { NotionParent } from "@notionhq/custom-blocks-protocol/parent.js"
import type { NotionTheme } from "@notionhq/custom-blocks-protocol/theme.js"
import type { NotionUser } from "@notionhq/custom-blocks-protocol/users/user.js"
import type {
	NotionDataSourcePage,
	NotionDataSourcePageUpdateArgs,
	UpdatePageResult,
} from "../types.js"

export type CustomBlockHostState = UninitializedHostState | InitializedHostState

export type UninitializedHostState = {
	status: "uninitialized"
	theme: NotionTheme
	contrastMode: NotionContrastMode
}

export type InitializedHostState = {
	status: "initialized"
	theme: NotionTheme
	contrastMode: NotionContrastMode
	blockId: NotionBlockId
	parent: NotionParent
	page: CustomBlockPage
	currentUser: NotionUser
	manifest: CustomBlockManifest
	dataSources: NotionDataSource[]
	dataSourceState: Record<string, DataSourceQueryState>
}

export type DataSourceQueryState = {
	dataSourceKey: string
	/** Latest pages from the host as parsed from the bridge. `propertiesByKey` is derived lazily. */
	items: NotionDataSourcePageBridge[]
	isLoading: boolean
	hasMore: boolean
	error?: CustomBlockQueryDataSourceErrorInfo
	latestLimit?: number
	latestQueryIdentity?: string
}

export function createEmptyDataSourceQueryState(
	dataSourceKey: string,
): DataSourceQueryState {
	return {
		dataSourceKey,
		items: [],
		isLoading: false,
		hasMore: false,
	}
}

/**
 * Resolved page + schema views for a single data source, keyed by raw property
 * ID and by user-defined key. Re-derived from `propertyIdsByKey` on every read so
 * renames don't require a re-query.
 */
export type DataSourceQueryView = {
	items: NotionDataSourcePage[]
	collectionSchema?: NotionDataSource["collectionSchema"]
	propertySchemasById: { [propertyId: string]: NotionPropertySchema }
	propertyIdsByKey: { [key: string]: string | undefined }
	propertySchemasByKey: { [key: string]: NotionPropertySchema | undefined }
	isLoading: boolean
	hasMore: boolean
	error?: CustomBlockQueryDataSourceErrorInfo
}

const EMPTY_QUERY_VIEW: DataSourceQueryView = {
	items: [],
	propertySchemasById: {},
	propertyIdsByKey: {},
	propertySchemasByKey: {},
	isLoading: false,
	hasMore: false,
}

/**
 * Per-row callback that resolves property keys against the data source and forwards the
 * resulting write to the bridge. Injected by callers (typically the SDK singleton in `init.ts`)
 * so this module stays free of bridge-instance dependencies.
 */
export type UpdateDataSourcePageFn = (args: {
	dataSource: NotionDataSource
	pageId: NotionPageId
	pageUpdateArgs: NotionDataSourcePageUpdateArgs
}) => Promise<UpdatePageResult>

export function getDataSourceQueryView(
	hostState: CustomBlockHostState,
	key: string,
	subscriptionId: string,
	updateDataSourcePage: UpdateDataSourcePageFn,
): DataSourceQueryView {
	if (hostState.status !== "initialized") {
		return EMPTY_QUERY_VIEW
	}

	const dataSource = hostState.dataSources.find(entry => entry.key === key)
	const subscriptionState = hostState.dataSourceState[subscriptionId]
	const queryState =
		subscriptionState?.dataSourceKey === key
			? subscriptionState
			: createEmptyDataSourceQueryState(key)

	if (dataSource === undefined) {
		return {
			items: [],
			collectionSchema: undefined,
			propertySchemasById: {},
			propertyIdsByKey: {},
			propertySchemasByKey: {},
			isLoading: queryState.isLoading,
			hasMore: queryState.hasMore,
			error: queryState.error,
		}
	}

	const propertyIdsByKey = dataSource.propertyIdsByKey
	const propertySchemasById = dataSource.propertySchemasById

	const resolvedItems: NotionDataSourcePage[] = queryState.items.map(entry => {
		const propertiesByKey: {
			[key: string]: NotionDataSourceValue | undefined
		} = {}
		for (const [key, propertyId] of Object.entries(propertyIdsByKey)) {
			propertiesByKey[key] =
				propertyId === undefined ? undefined : entry.propertiesById[propertyId]
		}
		const update = (args: NotionDataSourcePageUpdateArgs) =>
			updateDataSourcePage({
				dataSource,
				pageId: entry.id,
				pageUpdateArgs: args,
			})
		return {
			id: entry.id,
			is_archived: entry.is_archived,
			in_trash: entry.in_trash,
			propertiesById: entry.propertiesById,
			propertiesByKey,
			update,
			archive: () => update({ is_archived: true }),
			unarchive: () => update({ is_archived: false }),
		}
	})

	const propertySchemasByKey: {
		[key: string]: NotionPropertySchema | undefined
	} = {}
	for (const [key, propertyId] of Object.entries(propertyIdsByKey)) {
		propertySchemasByKey[key] =
			propertyId === undefined ? undefined : propertySchemasById[propertyId]
	}

	return {
		items: resolvedItems,
		collectionSchema: dataSource.collectionSchema,
		propertySchemasById,
		propertyIdsByKey,
		propertySchemasByKey,
		isLoading: queryState.isLoading,
		hasMore: queryState.hasMore,
		error: queryState.error,
	}
}
